const fs = require('fs');
const path = require('path');

// licenses.json is committed at the repo root and regenerated by
// scripts/analyze-licenses. In production the webpack CopyWebpackPlugin
// copies it into dist/, but for `yarn dev` (where webpack-dev-server serves
// the bundle from memory) we hand it back here.
const LICENSES_FILE = path.resolve(__dirname, '..', '..', 'licenses.json');

module.exports = function(req, res, next) {
  // We do this redirect so that /verify-auth can work with both standalone
  // and hosted configurations.
  if (req.url.includes('/verify-auth') || req.url.includes('/verify-auth-azure')) {
    res.writeHead(301, { Location: req.url.replace(/verify-auth(-azure)?/, 'auth/verify') });
    res.end();

    return;
  }

  // Serve licenses.json from the filesystem in development
  if (req.method === 'GET' && req.url === '/licenses.json') {
    if (fs.existsSync(LICENSES_FILE)) {
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      fs.createReadStream(LICENSES_FILE).pipe(res);
    } else {
      res.writeHead(404, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'licenses.json not found' }));
    }

    return;
  }

  next();
};
